const urls = [
  'http://localhost:3456/products/lamp?currency=EUR',
  'http://localhost:3456/products/lamp?currency=USD',
  'http://localhost:3456/products/vase',
  'http://localhost:3456/products/lamp?currency=EUR',
  'http://localhost:3456/products/missing',
];
for (const url of urls) {
  const started = Date.now();
  const res = await fetch(url);
  const html = await res.text();
  const name = html.match(/<h1>([^<]*)<\/h1>/)?.[1] ?? null;
  const price = html.match(/<h1>[^<]*<\/h1><p>([^<]*)<\/p>/)?.[1] ?? null;
  const related = [...html.matchAll(/<h2>Related products<\/h2>([\s\S]*?)<\/section>/g)].map(m => m[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
  console.log(JSON.stringify({
    url,
    status: res.status,
    ms: Date.now() - started,
    name,
    price,
    related,
    hasFrame: html.includes('Signal Shop collection') && html.includes('>Signal Shop<'),
  }));
}
"

